={
  "model": "claude-sonnet-4-6",
  "max_tokens": 4000,
  "tools": [
    {
      "name": "plan_content",
      "description": "Plan on-brand repurposed content for a blog post across a main blog image and three social platforms.",
      "input_schema": {
        "type": "object",
        "properties": {
          "main": {
            "type": "object",
            "properties": {
              "headline": { "type": "string", "description": "Short headline for the main blog image." },
              "image_prompt": { "type": "string", "description": "Visual description for the main blog image: subject, composition, and medium only." }
            },
            "required": ["headline", "image_prompt"]
          },
          "instagram": {
            "type": "object",
            "properties": {
              "headline": { "type": "string", "description": "Short in-image headline." },
              "caption": { "type": "string", "description": "Instagram caption adapted to the audience, conversational, with a few relevant hashtags." },
              "image_prompt": { "type": "string", "description": "Visual description for the Instagram image: subject, composition, and medium only." }
            },
            "required": ["headline", "caption", "image_prompt"]
          },
          "linkedin": {
            "type": "object",
            "properties": {
              "headline": { "type": "string", "description": "Short in-image headline." },
              "caption": { "type": "string", "description": "LinkedIn caption with a professional, insight-driven tone." },
              "image_prompt": { "type": "string", "description": "Visual description for the LinkedIn image: subject, composition, and medium only." }
            },
            "required": ["headline", "caption", "image_prompt"]
          },
          "twitter": {
            "type": "object",
            "properties": {
              "headline": { "type": "string", "description": "Short in-image headline." },
              "caption": { "type": "string", "description": "Concise tweet under 280 characters." },
              "image_prompt": { "type": "string", "description": "Visual description for the Twitter/X image: subject, composition, and medium only." }
            },
            "required": ["headline", "caption", "image_prompt"]
          }
        },
        "required": ["main", "instagram", "linkedin", "twitter"]
      }
    }
  ],
  "tool_choice": { "type": "tool", "name": "plan_content" },
  "messages": [
    {
      "role": "user",
      "content": {{ JSON.stringify("You are a brand marketing assistant. Repurpose the following blog post into on-brand visual content. Produce a main blog image plan plus a caption and image plan for Instagram, LinkedIn, and Twitter/X. Adapt each caption to that platform's audience and tone.\n\nImage prompt rules: describe only the subject (what is in the frame), the composition (how it is arranged), and optionally the medium (photograph, illustration, 3D render). Do not use aesthetic adjectives such as sleek, modern, premium, minimalist, or futuristic, and do not describe colors, fonts, or visual style; the brand layer applies all styling on its own, so style words either duplicate it or fight it. Avoid generic person-at-a-laptop or team-in-an-office scenes. Negative constraints (such as no humans, no UI mockups) are allowed and useful.\n\nHeadline rules: take a position instead of listing attributes, prefer concrete numbers over vague claims, and write in the register of that platform's audience rather than marketing-speak. Keep every headline short enough to render legibly inside an image.\n\nBlog title: " + $json.title + "\nAuthor: " + ($json.author || "unknown") + "\nURL: " + ($json.url || "") + "\n\nBlog body:\n" + $json.body) }}
    }
  ]
}

parameters.jsCode:
// Read Claude's structured tool_use output (guaranteed JSON, no text parsing)
const msg = $input.first().json;
const toolUse = (msg.content || []).find((block) => block.type === 'tool_use');
if (!toolUse || !toolUse.input) {
  throw new Error('Claude did not return a plan_content tool_use block.');
}
const plan = toolUse.input;

// Render guidance appended to every image prompt. Brand styling (colors, typography,
// aesthetic) is deliberately not prompted: Bloom's brand layer applies it via brandSessionId,
// and restating it in the prompt duplicates or fights that layer.
const BRAND_GUIDANCE =
  'Render the headline inside the image, bold and legible. ' +
  'One clear focal point. No fine print, no placeholder text, no watermark, no busy layout.';

// Aspect ratio + output filename are assigned deterministically per platform.
const platforms = [
  { platform: 'main',      aspectRatio: '16:9', basename: 'blog-main', plan: plan.main },
  { platform: 'instagram', aspectRatio: '4:5',  basename: 'instagram', plan: plan.instagram },
  { platform: 'linkedin',  aspectRatio: '1:1',  basename: 'linkedin',  plan: plan.linkedin },
  { platform: 'twitter',   aspectRatio: '16:9', basename: 'twitter',   plan: plan.twitter },
];

return platforms.map((p) => {
  if (!p.plan) {
    throw new Error(`Claude plan is missing the "${p.platform}" section.`);
  }
  return {
    json: {
      platform: p.platform,
      aspectRatio: p.aspectRatio,
      basename: p.basename,
      headline: p.plan.headline,
      caption: p.plan.caption || '',
      image_prompt: `${p.plan.image_prompt}\n\nHeadline: "${p.plan.headline}".\n${BRAND_GUIDANCE}`,
    },
  };
});

// Label each downloaded image with its platform filename so the ZIP is readable,
// and carry the caption/headline alongside the binary as metadata.
return $input.all().map((item, i) => {
  // itemMatching follows n8n's item pairing instead of assuming index alignment,
  // so labels stay correct even if an upstream node drops or reorders items.
  const job = $('Build platform jobs').itemMatching(i).json;
  if (!job || !job.basename) {
    throw new Error(`Could not pair downloaded image #${i} with its platform job.`);
  }
  const binary = item.binary.data;
  // The file extension follows the format Bloom actually served, not a hardcoded .png.
  const ext = (binary.fileExtension || (binary.mimeType || '').split('/')[1] || 'png').replace('jpeg', 'jpg');
  const filename = `${job.basename}.${ext}`;
  binary.fileName = filename;
  return {
    json: {
      platform: job.platform,
      filename,
      aspectRatio: job.aspectRatio,
      headline: job.headline,
      caption: job.caption,
    },
    binary: { data: binary },
  };
});
